const NAV_TARGET = {
  Bags: 'catalog-bags.html',
  Womenswear: 'catalog-womenswear.html',
  Menswear: 'catalog-menswear.html',
  Watches: 'catalog-watches.html'
};
for (const [label, html] of Object.entries(MENUS)) {
  const btn = [...document.querySelectorAll('header button, nav button')]
    .find(b => b.textContent.trim() === label);
  if (!btn) continue;
  const wrap = btn.parentElement;
  const tpl = document.createElement('template');
  tpl.innerHTML = html.trim();
  const panel = tpl.content.firstElementChild;
  panel.style.display = 'none';
  wrap.appendChild(panel);
  let hideTimer;
  wrap.addEventListener('mouseenter', () => {
    clearTimeout(hideTimer);
    document.querySelectorAll('.sc-menu-open').forEach(p => {
      p.classList.remove('sc-menu-open');
      p.style.display = 'none';
    });
    panel.style.display = '';
    panel.classList.add('sc-menu-open');
  });
  wrap.addEventListener('mouseleave', () => {
    hideTimer = setTimeout(() => {
      panel.style.display = 'none';
      panel.classList.remove('sc-menu-open');
    }, 150);
  });
  btn.addEventListener('click', () => { location.href = NAV_TARGET[label]; });
}
